using System.Runtime.InteropServices;

class C
{    
    [DllImport("D.DLL")]
    void F1() { }

    [DllImport("D.DLL")]
    enum E1 { a, b, c, d };

    [DllImport("D.DLL")]
    int F2(int bufSize, string buf);

    [DllImport("D.DLL")]
    public static int i =2;

    [DllImport("d.dll")]
    int F3 { get {return 0;}}

    [DllImport("D.DLL"), DllImport("GDI.DLL")]
    static extern int F4(int bufSize, string buf);

    void F5()
    {
       [DllImport("d.dll")]
       int loc = i;
    }         
}

[DllImport("dd.dllL")]
public class C1 { }

[DllImport("dd.dll")]
public class C2 { }

